/**
 * Per-user daily nutrition targets (calories + macros).
 *
 * - Targets depend ONLY on the user's age, gender, height, weight and goal.
 * - They are generated by the AI (validated against a deterministic baseline, with the formula as a
 *   fallback when the AI is unavailable or answers something implausible) and STORED in the
 *   `NutritionTarget` collection - exactly one document per user, including the profile snapshot
 *   they were generated from.
 * - Changing the profile does NOT silently change the targets: the app shows a "profile changed"
 *   hint and the user presses "Regenerate" (`POST /api/nutrition/targets/regenerate`).
 * - Every screen / engine (home, wellness engine, AI tools, chat, reminders) reads the targets via
 *   `getUserTargets`, so they always show the same numbers.
 */
const NutritionTarget = require('../nutrition/nutritionTarget.model');
const User = require('../modules/user/user.model');
const llm = require('../modules/ai/context/llm');
const {
  calculateNutritionTargets,
  NUTRITION_FORMULA_VERSION,
  MIN_CALORIES,
  MAX_CALORIES,
} = require('./macros');
const logger = require('./logger');

const GOALS = ['fat_loss', 'strength_building', 'maintenance'];
const GOAL_LABELS = {
  fat_loss: 'Fat Loss',
  strength_building: 'Strength Building',
  maintenance: 'Maintenance',
};
const FIELD_LABELS = { age: 'age', gender: 'gender', heightCm: 'height', weightKg: 'weight', goal: 'goal' };

// Values used ONLY by automatic generation (onboarding) when a profile field is still empty
const ASSUMED = { age: 30, gender: 'male', heightCm: 170, weightKg: 70, goal: 'maintenance' };

const AI_TIMEOUT_MS = 8000;

const num = v => (Number.isFinite(Number(v)) ? Number(v) : null);

/** The profile fields the targets are based on. */
const profileInputs = user => ({
  age: num(user.age),
  gender: user.gender || null,
  heightCm: num(user.height),
  weightKg: num(user.weight),
  goal: GOALS.includes(user.goalType) ? user.goalType : null,
});

const missingFields = inputs =>
  Object.keys(FIELD_LABELS).filter(key => inputs[key] === null || inputs[key] === undefined);

/** Stable string used to detect that the profile changed since the targets were generated. */
const fingerprint = inputs =>
  [inputs?.age, inputs?.gender, inputs?.heightCm, inputs?.weightKg, inputs?.goal].map(v => v ?? '').join('|');

const validationError = message => {
  const error = new Error(message);
  error.name = 'ValidationError';
  error.statusCode = 400;
  return error;
};

// ------------------------------------------------------------------ AI generation
const SYSTEM_PROMPT = `You are a registered sports dietitian. Work out the daily calorie and macronutrient targets for ONE person using only the data provided.
Rules:
- Base everything on age, gender, height, weight and goal. Do not assume anything else about the person.
- Use the baseline numbers as an anchor: calories must stay within 10% of "goalCalories" unless the person's body size clearly justifies a small correction.
- Protein 1.6-2.2 g per kg body weight, fat at least 0.8 g per kg (and 20-35% of calories), carbohydrates fill the remaining calories.
- protein*4 + carbs*4 + fat*9 must equal calories (within 3%).
- "rationale": max 40 words, plain language, mention their goal and body size. No emojis, no medical advice.
Return ONLY JSON: {"calories": integer, "protein": integer, "carbs": integer, "fat": integer, "rationale": string}`;

/** Accept the AI answer only when it is plausible; returns normalised targets or throws. */
const validateAiTargets = (raw, baseline, weightKg) => {
  const calories = Math.round(Number(raw.calories));
  let protein = Math.round(Number(raw.protein));
  const fat = Math.round(Number(raw.fat));
  let carbs = Math.round(Number(raw.carbs));
  if (![calories, protein, fat, carbs].every(Number.isFinite)) throw new Error('AI targets are not numbers');

  const lo = Math.max(MIN_CALORIES, Math.round(baseline.calorieTarget * 0.88));
  const hi = Math.min(MAX_CALORIES, Math.round(baseline.calorieTarget * 1.12));
  if (calories < lo || calories > hi) throw new Error(`AI calories ${calories} outside ${lo}-${hi}`);

  if (protein < weightKg * 1.2 || protein > weightKg * 2.6 || protein * 4 > calories * 0.4) {
    throw new Error(`AI protein ${protein} g implausible`);
  }
  if (fat < weightKg * 0.6 || fat * 9 > calories * 0.4) throw new Error(`AI fat ${fat} g implausible`);

  // keep the numbers internally consistent: carbs absorb any rounding gap
  const macroKcal = protein * 4 + carbs * 4 + fat * 9;
  if (Math.abs(macroKcal - calories) > calories * 0.05) {
    carbs = Math.round((calories - protein * 4 - fat * 9) / 4);
  }
  if (carbs < 40) throw new Error(`AI carbs ${carbs} g implausible`);

  return { calories, protein, carbs, fat };
};

const generateWithAi = async (inputs, baseline) => {
  const payload = {
    age: inputs.age,
    gender: inputs.gender,
    heightCm: inputs.heightCm,
    weightKg: inputs.weightKg,
    goal: GOAL_LABELS[inputs.goal] || inputs.goal,
    bmr: baseline.bmr,
    maintenanceCalories: baseline.maintenanceCalories,
    goalCalories: baseline.calorieTarget,
  };

  const { content, model } = await llm.complete({
    json: true,
    maxTokens: 220,
    temperature: 0.2,
    timeoutMs: AI_TIMEOUT_MS,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: `<person>\n${JSON.stringify(payload)}\n</person>` },
    ],
  });

  const parsed = JSON.parse(content);
  const targets = validateAiTargets(parsed, baseline, inputs.weightKg);
  const rationale = String(parsed.rationale || '').trim().slice(0, 600) || null;
  return { ...targets, rationale, model };
};

const goalSentence = inputs =>
  ({
    fat_loss: 'a moderate calorie deficit with high protein to protect muscle while losing fat',
    strength_building: 'a small calorie surplus with plenty of protein and carbs to build strength',
    maintenance: 'maintenance calories with balanced macros',
  })[inputs.goal] || 'balanced macros';

// ------------------------------------------------------------------ generate + store
/**
 * Generate this user's targets and store them (one document per user).
 *
 * @param {string} userId
 * @param {{strict?: boolean, allowAI?: boolean}} options
 *   strict  - true: every profile field must be filled (explicit "Regenerate"); false: missing
 *             fields are replaced by neutral defaults and listed in `inputs.assumed` (automatic
 *             generation during onboarding).
 *   allowAI - false skips the OpenAI call (instant formula result).
 */
const generateTargets = async (userId, { strict = true, allowAI = true } = {}) => {
  const user = await User.findById(userId);
  if (!user) {
    const error = new Error('User not found');
    error.statusCode = 404;
    throw error;
  }

  const inputs = profileInputs(user);
  const missing = missingFields(inputs);
  const assumed = [];

  if (missing.length) {
    if (strict) {
      throw validationError(
        `Add your ${missing.map(key => FIELD_LABELS[key]).join(', ')} in Edit Profile to generate targets.`,
      );
    }
    missing.forEach(key => {
      inputs[key] = ASSUMED[key];
      assumed.push(key);
    });
  }

  const baseline = calculateNutritionTargets({
    goalType: inputs.goal,
    height: inputs.heightCm,
    weight: inputs.weightKg,
    age: inputs.age,
    gender: inputs.gender,
  });

  let source = 'formula';
  let model = null;
  let rationale = null;
  let result = {
    calories: baseline.calorieTarget,
    protein: baseline.proteinTarget,
    carbs: baseline.carbTarget,
    fat: baseline.fatTarget,
  };

  if (allowAI && llm.isConfigured()) {
    try {
      const ai = await generateWithAi(inputs, baseline);
      result = { calories: ai.calories, protein: ai.protein, carbs: ai.carbs, fat: ai.fat };
      rationale = ai.rationale;
      model = ai.model;
      source = 'ai';
    } catch (error) {
      logger.warn(`AI nutrition targets unavailable for ${userId}, using formula: ${error.message}`);
    }
  }

  if (!rationale) {
    rationale =
      `Calculated from your age, gender, height and weight (about ${baseline.maintenanceCalories} kcal to maintain) ` +
      `with ${goalSentence(inputs)}.`;
  }

  const ratio = (grams, kcal) => Math.round(((grams * kcal) / result.calories) * 100) / 100;

  return NutritionTarget.findOneAndUpdate(
    { userId },
    {
      userId,
      calorieTarget: result.calories,
      proteinTarget: result.protein,
      carbTarget: result.carbs,
      fatTarget: result.fat,
      proteinRatio: ratio(result.protein, 4),
      carbRatio: ratio(result.carbs, 4),
      fatRatio: ratio(result.fat, 9),
      maintenanceCalories: baseline.maintenanceCalories,
      bmr: baseline.bmr,
      source,
      model,
      rationale,
      isCustom: false,
      formulaVersion: NUTRITION_FORMULA_VERSION,
      inputs: { ...inputs, assumed },
      generatedAt: new Date(),
      lastUpdated: new Date(),
    },
    { upsert: true, returnDocument: 'after', runValidators: true, setDefaultsOnInsert: true },
  );
};

// ------------------------------------------------------------------ read
/**
 * The user's saved targets. Creates them (formula, instant) the first time when the profile is
 * complete, and refreshes legacy formula-generated rows that predate the stored profile snapshot.
 * AI-generated and hand-edited targets are never replaced here.
 */
const getUserTargets = async userId => {
  const saved = await NutritionTarget.findOne({ userId });

  try {
    if (!saved) {
      const user = await User.findById(userId).select('age gender height weight goalType');
      if (user && missingFields(profileInputs(user)).length === 0) {
        return await generateTargets(userId, { strict: true, allowAI: false });
      }
      return null;
    }

    const legacy = !saved.isCustom && saved.source !== 'ai' && (saved.formulaVersion || 1) < NUTRITION_FORMULA_VERSION;
    if (legacy) return await generateTargets(userId, { strict: false, allowAI: false });
  } catch (error) {
    logger.error(`Nutrition target lookup failed: ${error.message}`);
  }

  return saved;
};

/**
 * Targets + everything the "Personal information" screen needs: where they came from, what they
 * were based on, whether the profile changed since, and which profile fields are still missing.
 */
const describeTargets = async userId => {
  const [targets, user] = await Promise.all([
    getUserTargets(userId),
    User.findById(userId).select('age gender height weight goalType'),
  ]);
  if (!user) {
    const error = new Error('User not found');
    error.statusCode = 404;
    throw error;
  }

  const current = profileInputs(user);
  const missing = missingFields(current).map(key => FIELD_LABELS[key]);
  const base = targets ? targets.toObject() : null;

  return {
    targets: base && {
      calories: base.calorieTarget,
      protein: base.proteinTarget,
      carbs: base.carbTarget,
      fat: base.fatTarget,
    },
    meta: {
      exists: !!base,
      source: base ? (base.isCustom ? 'custom' : base.source || 'formula') : null,
      model: base?.model || null,
      rationale: base?.rationale || null,
      generatedAt: base?.generatedAt || base?.lastUpdated || null,
      basedOn: base?.inputs || null,
      currentProfile: current,
      missing,
      // profile changed since the targets were generated -> offer "Regenerate"
      // (targets saved before the snapshot existed have no snapshot to compare with)
      isStale:
        !!base &&
        !!base.inputs &&
        (base.inputs.age != null || base.inputs.goal != null) &&
        fingerprint(base.inputs) !== fingerprint(current),
      isCustom: !!base?.isCustom,
      maintenanceCalories: base?.maintenanceCalories || null,
    },
  };
};

module.exports = {
  getUserTargets,
  generateTargets,
  describeTargets,
  profileInputs,
  validateAiTargets, // exported for tests
};
